def plus_longue_hausse(temp):
    meilleur = 1
    courant = 1
    for i in range(1, len(temp)):
        if temp[i] > temp[i - 1]:
            courant = courant + 1
        else:
            courant = 1
        if courant > meilleur:
            meilleur = courant
    return meilleur
```

