def moyenne_sans_extremes(notes):
    mini = notes[0]
    maxi = notes[0]
    total = 0
    for n in notes:
        total += n
        if n < mini:
            mini = n
        if n > maxi:
            maxi = n
    return (total - mini - maxi) / (len(notes) - 2)
